const cfg = {
  baseUrl: "https://api.peach-in.com/v4",
  apiKey: "REPLACE_ME",
  authScheme: "Bearer",
  // "nativeGroups" uses Peach's built-in contact `groups` array.
  // "customProperty" stores the group list inside one custom field instead.
  groupSyncMode: "nativeGroups",
  groupsField: "whatsapp_groups",
  // "e164" (+972501234567) or "local-il" (0501234567)
  phoneFormat: "e164",
  defaultFirstName: "WhatsApp",
  defaultLastNamePrefix: "Contact",
  // set to "" to omit email instead of sending a placeholder
  placeholderEmailDomain: "whatsapp.invalid"
};

function formatPhone(raw, format) {
  if (!raw) return raw;
  if (format === 'local-il' && raw.startsWith('972')) return '0' + raw.slice(3);
  if (format === 'e164') return raw.startsWith('+') ? raw : '+' + raw;
  return raw;
}

const rawPhone = $json.rawPhone;
const phone = formatPhone(rawPhone, cfg.phoneFormat);
// Peach's get-contact doc example searched by local-IL format ("0587701234"),
// so the lookup always uses that format regardless of PEACH storage format.
const lookupPhone = formatPhone(rawPhone, 'local-il');
const firstName = $json.firstName || cfg.defaultFirstName;
const lastName = $json.lastName || (cfg.defaultLastNamePrefix + ' ' + rawPhone);
const email = cfg.placeholderEmailDomain ? (rawPhone + '@' + cfg.placeholderEmailDomain) : undefined;

return {
  json: {
    rawPhone,
    groupLabel: $json.groupLabel,
    phone,
    lookupPhone,
    firstName,
    lastName,
    email,
    peachBaseUrl: cfg.baseUrl,
    peachApiKey: cfg.apiKey,
    peachAuthScheme: cfg.authScheme,
    groupSyncMode: cfg.groupSyncMode,
    groupsField: cfg.groupsField
  }
};

const input = $('Peach Config and derive').item.json;
const resp = $json || {};
const existing = (resp.contacts && resp.contacts[0]) || null;

let action, body, contactId;

if (!existing) {
  action = 'create';
  body = { firstName: input.firstName, lastName: input.lastName, phone: input.phone };
  if (input.email) body.email = input.email;
  if (input.groupSyncMode === 'nativeGroups') {
    body.groups = [input.groupLabel];
  } else {
    body.customProperties = { [input.groupsField]: input.groupLabel };
  }
} else {
  contactId = existing.contactId;
  if (input.groupSyncMode === 'nativeGroups') {
    const currentGroups = existing.groups || [];
    if (currentGroups.includes(input.groupLabel)) {
      action = 'skip';
    } else {
      action = 'update';
      body = { groups: [input.groupLabel] };
    }
  } else {
    const raw = (existing.customProperties && existing.customProperties[input.groupsField]) || '';
    const currentGroups = String(raw).split(',').map(s => s.trim()).filter(Boolean);
    if (currentGroups.includes(input.groupLabel)) {
      action = 'skip';
    } else {
      action = 'update';
      body = { customProperties: { [input.groupsField]: [...currentGroups, input.groupLabel].join(', ') } };
    }
  }
}

return { json: { ...input, action, body, contactId } };
